sys_ws_operation.operation_script:
(function process(request, response) {
    var gr = new GlideRecord('incident');
    gr.addQuery('active', 'true');
    gr.query();
    var results = [];
    while (gr.next()) {
        results.push(gr.number.toString());
    }
    response.setBody(JSON.stringify(results));
})(request, response);
